using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Build.Reporting;
public static class BuildSchoolWindows {
public static string Run(){if(EditorApplication.isPlaying||BuildPipeline.isBuildingPlayer)throw new Exception("Idle Editor required");string output=Path.GetFullPath("../Builds/SchoolExpansion/FireSafetyTraining.exe");string report=Path.GetFullPath("../Documentation/SchoolWindowsBuild.json");Directory.CreateDirectory(Path.GetDirectoryName(output));EditorApplication.delayCall+=()=>{try{var r=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/_FireSafety/Scenes/TrainingScene.unity"},locationPathName=output,target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});File.WriteAllText(report,Newtonsoft.Json.JsonConvert.SerializeObject(new{result=r.summary.result.ToString(),r.summary.totalErrors,r.summary.totalWarnings,seconds=r.summary.totalTime.TotalSeconds,r.summary.totalSize,output,issues=r.steps.SelectMany(s=>s.messages).Where(m=>m.type==LogType.Error||m.type==LogType.Warning||m.type==LogType.Exception).Select(m=>m.content).ToArray()},Newtonsoft.Json.Formatting.Indented));}catch(Exception e){File.WriteAllText(report,e.ToString());}};return "Queued release build to "+output;}}
